from .units import g_to_kg, kg_to_g, normalize_kg

MAX_PARCEL_KG = "20.000"
_MAX_PARCEL_G = kg_to_g(MAX_PARCEL_KG)


class Parcel:
    def __init__(self, weight_kg, skus):
        self.weight_kg = normalize_kg(weight_kg)
        self.skus = list(skus)

    def add(self, weight_kg, sku):
        self.weight_kg = g_to_kg(kg_to_g(self.weight_kg) + kg_to_g(weight_kg))
        self.skus.append(sku)


def split_parcels(order):
    """First-fit decreasing. A unit heavier than the limit travels alone."""
    units = []
    for item in order.items:
        units.extend((item.weight_kg, item.sku) for _ in range(item.qty))
    units.sort(key=lambda unit: (-kg_to_g(unit[0]), unit[1]))
    parcels = []
    for weight_kg, sku in units:
        grams = kg_to_g(weight_kg)
        for parcel in parcels:
            if kg_to_g(parcel.weight_kg) + grams <= _MAX_PARCEL_G:
                parcel.add(weight_kg, sku)
                break
        else:
            parcels.append(Parcel(weight_kg, [sku]))
    return parcels

