import json

from .models import Item, Order
from .units import g_to_kg

SCHEMA = 2


def save(order, path):
    data = {"schema": SCHEMA, "items": [item.to_dict() for item in order.items]}
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(data, handle, indent=2, sort_keys=True)
        handle.write("\n")


def _item(raw, schema):
    if schema == 1:  # legacy: whole grams
        return Item(raw["sku"], g_to_kg(raw["weight_g"]), raw.get("qty", 1))
    return Item.from_dict(raw)


def load(path):
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
    schema = data.get("schema")
    if schema not in (1, SCHEMA):
        raise ValueError(f"unsupported schema: {schema!r}")
    return Order(_item(raw, schema) for raw in data["items"])

