def validate_item(data):
    """Return a list of problems, each 'field: reason'. Empty means valid."""
    problems = []
    for name, (kind, low, high) in RULES.items():
        if name not in data:
            problems.append(f"{name}: missing")
            continue
        value = data[name]
        if kind == "str":
            if not isinstance(value, str):
                problems.append(f"{name}: not a string")
            elif not int(low) <= len(value) <= int(high):
                problems.append(f"{name}: length out of range {low}..{high}")
        elif kind == "int":
            if isinstance(value, bool) or not isinstance(value, int):
                problems.append(f"{name}: not an integer")
            elif not int(low) <= value <= int(high):
                problems.append(f"{name}: out of range {low}..{high}")
        else:  # kg: rounded first, then the range is checked
            try:
                canonical = normalize_kg(value)
            except WeightError as exc:
                problems.append(f"{name}: {exc}")
                continue
            if not kg_to_g(low) <= kg_to_g(canonical) <= kg_to_g(high):
                problems.append(f"{name}: out of range {low}..{high}")
