import contextlib
import io
import json
import os
import tempfile
import unittest

from shipcalc import cache, cli, export, format as fmt, limits, reports, storage, validate
from shipcalc.calc import order_weight_kg
from shipcalc.models import Item, Order
from shipcalc.units import WeightError, g_to_kg, kg_to_g, normalize_kg


class NormalizeTest(unittest.TestCase):
    def test_canonical_form(self):
        self.assertEqual(normalize_kg("2"), "2.000")
        self.assertEqual(normalize_kg("0.250"), "0.250")
        self.assertEqual(normalize_kg("1000.000"), "1000.000")

    def test_half_even_rounding(self):
        self.assertEqual(normalize_kg("1.0005"), "1.000")
        self.assertEqual(normalize_kg("1.0015"), "1.002")
        self.assertEqual(normalize_kg("2.0025"), "2.002")
        self.assertEqual(normalize_kg("1.2345"), "1.234")

    def test_invalid_input(self):
        for bad in ["-1", "+1", "1e3", "nan", "inf", "", " 1", "1 ", "1,5", "1.", ".5", ".", "1\n"]:
            with self.subTest(bad=bad), self.assertRaises(WeightError):
                normalize_kg(bad)
        for bad in [1, 1.5, True, None]:
            with self.subTest(bad=bad), self.assertRaises(WeightError):
                normalize_kg(bad)

    def test_error_message(self):
        with self.assertRaises(WeightError) as ctx:
            normalize_kg("abc")
        self.assertEqual(str(ctx.exception), "invalid weight: 'abc'")
        with self.assertRaises(ValueError) as ctx:
            normalize_kg(1500)
        self.assertEqual(str(ctx.exception), "invalid weight: 1500")


class GramConversionTest(unittest.TestCase):
    def test_g_to_kg(self):
        self.assertEqual(g_to_kg(1250), "1.250")
        self.assertEqual(g_to_kg(0), "0.000")

    def test_g_to_kg_rejects_other_types(self):
        for bad in [-1, 1.0, "1250", True, None]:
            with self.subTest(bad=bad), self.assertRaises(WeightError):
                g_to_kg(bad)

    def test_kg_to_g(self):
        self.assertEqual(kg_to_g("1.25"), 1250)
        self.assertIsInstance(kg_to_g("1.25"), int)
        self.assertEqual(kg_to_g("1.0015"), 1002)


class LimitTest(unittest.TestCase):
    def test_carrier_limit_is_inclusive(self):
        self.assertEqual(limits.check_total_kg("2147483.647"), "2147483.647")
        with self.assertRaises(WeightError):
            limits.check_total_kg("2147483.648")

    def test_order_over_limit_raises_weight_error(self):
        order = Order([Item("A", "1000.000", 2147), Item("B", "484.000")])
        with self.assertRaises(WeightError):
            order_weight_kg(order)


class ReportsTest(unittest.TestCase):
    def test_average_rounds_half_even(self):
        # 0.001 + 0.002 = 0.003 kg over 2 units: 1.5 g rounds to 2 g (even)
        order = Order([Item("A", "0.001"), Item("B", "0.002")])
        self.assertEqual(reports.average_weight_kg(order), "0.002")
        # 0.001 + 0.002 over 4 units (qty) -> 0.75 g rounds to 1 g
        order = Order([Item("A", "0.001", 1), Item("B", "0.002", 3)])
        self.assertEqual(reports.average_weight_kg(order), "0.002")

    def test_average_empty(self):
        self.assertEqual(reports.average_weight_kg(Order()), "0.000")

    def test_bands_keep_thresholds(self):
        order = Order([Item("L", "0.500"), Item("M", "0.501"), Item("M2", "2.000"), Item("H", "2.001")])
        self.assertEqual(reports.weight_bands(order), {"light": 1, "medium": 2, "heavy": 1})

    def test_heaviest_orders_numerically(self):
        order = Order([Item("B", "10.000"), Item("A", "9.500"), Item("C", "10.000")])
        self.assertEqual([i.sku for i in reports.heaviest(order)], ["B", "C", "A"])


class ValidateTest(unittest.TestCase):
    def test_weight_range_applies_after_rounding(self):
        self.assertIn("weight_kg: out of range 0.001..1000.000",
                      validate.validate_item({"sku": "A", "weight_kg": "0.0004", "qty": 1}))
        self.assertEqual(validate.validate_item({"sku": "A", "weight_kg": "1000.0004", "qty": 1}), [])

    def test_invalid_weight_is_a_problem(self):
        problems = validate.validate_item({"sku": "A", "weight_kg": "1,5", "qty": 1})
        self.assertEqual(problems, ["weight_kg: invalid weight: '1,5'"])

    def test_weight_g_is_missing_weight_kg(self):
        problems = validate.validate_item({"sku": "A", "weight_g": 500, "qty": 1})
        self.assertIn("weight_kg: missing", problems)


class StorageTest(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.path = os.path.join(self.dir.name, "order.json")

    def tearDown(self):
        self.dir.cleanup()

    def _write(self, data):
        with open(self.path, "w", encoding="utf-8") as handle:
            json.dump(data, handle)

    def test_save_writes_schema_2(self):
        storage.save(Order([Item("A", "1.5", 2)]), self.path)
        with open(self.path, encoding="utf-8") as handle:
            data = json.load(handle)
        self.assertEqual(data, {"schema": 2, "items": [{"sku": "A", "weight_kg": "1.500", "qty": 2}]})

    def test_load_schema_1_converts_grams(self):
        self._write({"schema": 1, "items": [{"sku": "A", "weight_g": 1250, "qty": 2}]})
        order = storage.load(self.path)
        self.assertEqual(order.items[0].weight_kg, "1.250")
        self.assertEqual(order.items[0].qty, 2)

    def test_load_schema_1_invalid_weight(self):
        self._write({"schema": 1, "items": [{"sku": "A", "weight_g": -5}]})
        with self.assertRaises(WeightError):
            storage.load(self.path)

    def test_load_schema_2_normalises(self):
        self._write({"schema": 2, "items": [{"sku": "A", "weight_kg": "0.0015", "qty": 1}]})
        self.assertEqual(storage.load(self.path).items[0].weight_kg, "0.002")

    def test_unknown_schema(self):
        self._write({"schema": 3, "items": []})
        with self.assertRaises(ValueError):
            storage.load(self.path)


class ExportTest(unittest.TestCase):
    def setUp(self):
        self.order = Order([Item("MUG-01", "0.350", 2), Item("BOOK-07", "1.200")])

    def test_csv_stays_in_grams(self):
        self.assertEqual(export.to_csv(self.order), "sku,weight_g,qty\nMUG-01,350,2\nBOOK-07,1200,1\n")

    def test_carrier_payload_is_int_grams(self):
        payload = export.carrier_payload(self.order)
        self.assertEqual(payload, {"weight_g": 1900, "parcels": 1})
        self.assertIs(type(payload["weight_g"]), int)


class FormatCacheTest(unittest.TestCase):
    def test_format_weight(self):
        self.assertEqual(fmt.format_weight("0.250"), "0.250 kg")
        self.assertEqual(fmt.format_weight("12.000"), "12.000 kg")

    def test_quote_key_is_v2(self):
        order = Order([Item("A", "1.000", 2)])
        self.assertEqual(cache.quote_key(order, "eu"), "quote:v2:eu:2.000:1")


class CliTest(unittest.TestCase):
    def test_add_rejects_grams_style_input(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "order.json")
            storage.save(Order(), path)
            err = io.StringIO()
            with contextlib.redirect_stderr(err), contextlib.redirect_stdout(io.StringIO()):
                status = cli.main(["add", path, "LAMP-3", "2400", "1"])
            self.assertEqual(status, 0)  # 2400 kg is a valid weight to the parser; limits apply in validate
            status = cli.main(["add", path, "LAMP-3", "abc", "1"])
            self.assertEqual(status, 2)
            self.assertIn("error: invalid weight: 'abc'", err.getvalue())


if __name__ == "__main__":
    unittest.main()

